    private Path createTempFilePath(String prefix) throws IOException {
        if (tempFileManager != null) {
            return tempFileManager.createTempFile(".tmp").toPath();
        }
        Path p = Files.createTempFile(prefix, ".tmp");
        p.toFile().deleteOnExit();
        return p;
