    public byte[] imageToPdf(
            MultipartFile[] files,
            String fitOption,
            boolean autoRotate,
            String colorType,
            CustomPDFDocumentFactory pdfDocumentFactory)
            throws IOException {
        return imageToPdf(files, fitOption, autoRotate, colorType, pdfDocumentFactory, false);
    }

    /**
     * Composes uploads in batch order, expanding TIFF frames in frame order. Each image retains its
     * colors and proportions, centered at the largest fitting size on A4 portrait, followed by an
     * empty A4 back, including the final image.
     *
     * <p>Uploads remain caller-owned; the document and all opened streams/readers are closed on
     * success or failure. Decoding is sequential and any failed input aborts the whole book.
     *
     * @throws IllegalArgumentException if the batch is absent, empty, or contains null/empty
     *     uploads
     * @throws IOException if any image or TIFF frame cannot be decoded or the PDF cannot be saved
     */
    public byte[] createColoringBook(
            MultipartFile[] files, CustomPDFDocumentFactory pdfDocumentFactory) throws IOException {
        if (files == null || files.length == 0) {
            throw new IllegalArgumentException("At least one image is required");
        }
        for (MultipartFile file : files) {
            if (file == null) {
                throw new IllegalArgumentException("An image upload is missing");
            }
            if (file.isEmpty()) {
                throw new IllegalArgumentException("Image is empty: " + imageInputName(file));
            }
        }
        return imageToPdf(files, "maintainAspectRatio", false, "color", pdfDocumentFactory, true);
    }

    private byte[] imageToPdf(
            MultipartFile[] files,
            String fitOption,
            boolean autoRotate,
            String colorType,
            CustomPDFDocumentFactory pdfDocumentFactory,
            boolean blankBacks)
            throws IOException {
        try (PDDocument doc = pdfDocumentFactory.createNewDocument()) {
            for (MultipartFile file : files) {
                try {
                    if (blankBacks ? hasTiffImageData(file) : isTiff(file)) {
                        appendTiffFrames(doc, file, fitOption, autoRotate, colorType, blankBacks);
                    } else {
                        appendSingleImage(doc, file, fitOption, autoRotate, colorType, blankBacks);
                    }
                } catch (IOException | RuntimeException e) {
                    if (!blankBacks) {
                        throw e;
                    }
                    throw new IOException("Unable to read image: " + imageInputName(file), e);
                }
            }
            ByteArrayOutputStream byteArrayOutputStream = new ByteArrayOutputStream();
            doc.save(byteArrayOutputStream);
            log.debug("PDF successfully saved to byte array");
            return byteArrayOutputStream.toByteArray();
        }
    }

    private String imageInputName(MultipartFile file) {
        String filename = Filenames.toSimpleFileName(file.getOriginalFilename());
        return filename == null || filename.isBlank()
                ? "unnamed image"
                : filename.replaceAll("\\p{Cntrl}", "");
    }

    private boolean hasTiffImageData(MultipartFile file) throws IOException {
        try (InputStream input = file.getInputStream();
                ImageInputStream imageInput = ImageIO.createImageInputStream(input)) {
            if (imageInput == null) {
                throw new IOException("Unable to open image stream");
            }
            Iterator<ImageReader> readers = ImageIO.getImageReaders(imageInput);
            if (!readers.hasNext()) {
                throw new IOException("No image reader accepts this input");
            }
            ImageReader reader = readers.next();
            try {
                String format = reader.getFormatName();
                return "tiff".equalsIgnoreCase(format) || "tif".equalsIgnoreCase(format);
            } finally {
                reader.dispose();
            }
        }
    }

    /**
     * A TIFF is recognised by declared content type as well as filename suffix: an extensionless
     * upload would otherwise take the single-image path and silently drop every frame but one.
     */
    private boolean isTiff(MultipartFile file) {
        if (hasTiffContentType(file.getContentType())) {
            return true;
        }
        String filename = Filenames.toSimpleFileName(file.getOriginalFilename());
        return filename != null
                && (filename.toLowerCase(Locale.ROOT).endsWith(".tiff")
                        || filename.toLowerCase(Locale.ROOT).endsWith(".tif"));
    }

    /** Parsed, not compared whole: RFC 3302 allows parameters such as {@code application=}. */
    private boolean hasTiffContentType(String contentType) {
        if (contentType == null) {
            return false;
        }
        try {
            MediaType mediaType = MediaType.parseMediaType(contentType);
            return "image".equals(mediaType.getType())
                    && ("tiff".equals(mediaType.getSubtype())
                            || "x-tiff".equals(mediaType.getSubtype()));
        } catch (InvalidMediaTypeException e) {
            return false;
        }
    }

    /** Every frame becomes a page; streams and reader are released even when a frame fails. */
    private void appendTiffFrames(
            PDDocument doc,
            MultipartFile file,
            String fitOption,
            boolean autoRotate,
            String colorType,
            boolean blankBacks)
            throws IOException {
        try (InputStream input = file.getInputStream();
                ImageInputStream imageInput = ImageIO.createImageInputStream(input)) {
            ImageReader reader = ImageIO.getImageReadersByFormatName("tiff").next();
            try {
                reader.setInput(imageInput);
                int numPages = reader.getNumImages(true);
                for (int i = 0; i < numPages; i++) {
                    BufferedImage convertedImage =
                            ImageProcessingUtils.convertColorType(reader.read(i), colorType);
                    PDImageXObject pdImage = LosslessFactory.createFromImage(doc, convertedImage);
                    addImageToDocument(doc, pdImage, fitOption, autoRotate);
                    if (blankBacks) {
                        doc.addPage(new PDPage(PDRectangle.A4));
                    }
                }
            } finally {
                reader.dispose();
            }
        }
    }

    private void appendSingleImage(
            PDDocument doc,
            MultipartFile file,
            String fitOption,
            boolean autoRotate,
            String colorType,
            boolean blankBacks)
            throws IOException {
        BufferedImage image = ImageProcessingUtils.loadImageWithExifOrientation(file);
        BufferedImage convertedImage = ImageProcessingUtils.convertColorType(image, colorType);
        // Use JPEGFactory if it's JPEG since JPEG is lossy
        String contentType = file.getContentType();
        PDImageXObject pdImage =
                (contentType != null && MediaType.IMAGE_JPEG_VALUE.equals(contentType))
                        ? JPEGFactory.createFromImage(doc, convertedImage)
                        : LosslessFactory.createFromImage(doc, convertedImage);
        addImageToDocument(doc, pdImage, fitOption, autoRotate);
        if (blankBacks) {
            doc.addPage(new PDPage(PDRectangle.A4));
        }
    }

    public void addImageToDocument(
            PDDocument doc, PDImageXObject image, String fitOption, boolean autoRotate)
            throws IOException {
        boolean imageIsLandscape = image.getWidth() > image.getHeight();
        PDRectangle pageSize = PDRectangle.A4;

        if (autoRotate && imageIsLandscape) {
            pageSize = new PDRectangle(pageSize.getHeight(), pageSize.getWidth());
        }

        if ("fitDocumentToImage".equals(fitOption) || "fitDocumentToPage".equals(fitOption)) {
            pageSize = new PDRectangle(image.getWidth(), image.getHeight());
        }

        PDPage page = new PDPage(pageSize);
        doc.addPage(page);
        return op.filter(image, null);
    }

    /**
     * Decodes the first image and applies its EXIF rotation. The upload remains caller-owned; every
     * stream opened for decoding or metadata is closed before returning or propagating failure.
     */
    public static BufferedImage loadImageWithExifOrientation(MultipartFile file)
            throws IOException {
        BufferedImage image = null;
        String filename = file.getOriginalFilename();

        if (filename != null && filename.toLowerCase(Locale.ROOT).endsWith(".psd")) {
            // For PSD files, try explicit ImageReader
            Iterator<ImageReader> readers = ImageIO.getImageReadersByFormatName("PSD");
            if (readers.hasNext()) {
                ImageReader reader = readers.next();
                try (InputStream input = file.getInputStream();
                        ImageInputStream iis = ImageIO.createImageInputStream(input)) {
                    reader.setInput(iis);
                    image = reader.read(0);
                } finally {
                    reader.dispose();
                }
            }
            if (image == null) {
                throw new IOException(
                        "Unable to read image from file: "
                                + filename
                                + ". Supported PSD formats: RGB/CMYK/Gray 8-32 bit, RLE/ZIP"
                                + " compression");
            }
        } else {
            // For non-PSD files, use standard ImageIO
            try (InputStream input = file.getInputStream()) {
                image = ImageIO.read(input);
            }
        }

        if (image == null) {
            throw ExceptionUtils.createImageReadException(filename);
        }

        try (InputStream input = file.getInputStream()) {
            double orientation = extractImageOrientation(input);
            return applyOrientation(image, orientation);
        }
    }
}
package stirling.software.common.util;

