import org.apache.pdfbox.pdmodel.PDDocument;
import org.apache.pdfbox.pdmodel.PDPage;
import org.apache.pdfbox.pdmodel.common.PDRectangle;
import org.apache.pdfbox.rendering.PDFRenderer;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.CsvSource;
import org.springframework.mock.web.MockMultipartFile;
import org.springframework.web.multipart.MultipartFile;

import stirling.software.common.service.CustomPDFDocumentFactory;

class ColoringBookPdfTest {
    private CustomPDFDocumentFactory factory;
    private PDDocument composedDocument;

    @BeforeEach
    void setUp() throws IOException {
        composedDocument = new PDDocument();
        factory = mock(CustomPDFDocumentFactory.class);
        when(factory.createNewDocument()).thenReturn(composedDocument);
    }

    @AfterEach
    void closeFixtureDocument() throws IOException {
        composedDocument.close();
    }

    @Test
    void oneImageIncludesFinalBlankBack() throws IOException {
        try (PDDocument pdf = create(imageFile("one.png", "png", 40, 80, Color.RED))) {
            assertEquals(2, pdf.getNumberOfPages());
            assertBookPages(pdf, Color.RED);
        }
        assertTrue(composedDocument.getDocument().isClosed());
    }

    @Test
    void preservesBatchOrderAndColorsAcrossPngAndJpeg() throws IOException {
        try (PDDocument pdf =
                create(
                        imageFile("z.png", "png", 40, 80, Color.RED),
                        imageFile("a.jpg", "jpg", 80, 40, Color.GREEN),
                        imageFile("m.png", "png", 60, 60, Color.BLUE))) {
            assertEquals(6, pdf.getNumberOfPages());
            assertBookPages(pdf, Color.RED, Color.GREEN, Color.BLUE);
        }
    }

    @ParameterizedTest
    @CsvSource({"40,80", "60,60", "80,40"})
    void centersAndFitsImageOnPortraitA4(int width, int height) throws IOException {
        try (PDDocument pdf = create(imageFile("art.png", "png", width, height, Color.RED))) {
            assertPlacement(pdf.getPage(0), width, height);
            assertBookPages(pdf, Color.RED);
        }
    }

    @ParameterizedTest
    @CsvSource({"scan.tiff,image/tiff", "scan,image/tiff; application=foo", "scan.png,image/png"})
    void expandsEveryTiffFrameInOrderRegardlessOfDeclaredMetadata(String name, String mime)
            throws IOException {
        try (PDDocument pdf = create(new MockMultipartFile("fileInput", name, mime, tiff()))) {
            assertEquals(4, pdf.getNumberOfPages());
            assertBookPages(pdf, Color.RED, Color.BLUE);
        }
    }

    @Test
    void decodesPngDespiteTiffFilenameAndMime() throws IOException {
        MultipartFile file =
                new MockMultipartFile(
                        "fileInput",
                        "art.tiff",
                        "image/tiff",
                        encoded(solidImage(40, 80, Color.RED), "png"));
        try (PDDocument pdf = create(file)) {
            assertEquals(2, pdf.getNumberOfPages());
            assertBookPages(pdf, Color.RED);
        }
    }

    @Test
    void preservesExistingExifOrientationBeforePlacement() throws IOException {
        BufferedImage image = solidImage(60, 60, Color.BLUE);
        Graphics2D graphics = image.createGraphics();
        graphics.setColor(Color.RED);
        graphics.fillRect(0, 0, 30, 60);
        graphics.dispose();
        try (PDDocument pdf =
                create(
                        new MockMultipartFile(
                                "fileInput",
                                "rotated.jpg",
                                "image/jpeg",
                                jpegWithExifOrientation(encoded(image, "jpg"))))) {
            assertPlacement(pdf.getPage(0), 60, 60);
            BufferedImage rendered = new PDFRenderer(pdf).renderImage(0);
            assertColorNear(Color.RED, rendered.getRGB(rendered.getWidth() / 2, 260));
            assertColorNear(Color.BLUE, rendered.getRGB(rendered.getWidth() / 2, 580));
            assertBlank(pdf, 1);
        }
    }

    @Test
    void rejectsMissingOrEmptyBatch() {
        assertThrows(
                IllegalArgumentException.class, () -> PdfUtils.createColoringBook(null, factory));
        assertThrows(
                IllegalArgumentException.class,
                () -> PdfUtils.createColoringBook(new MultipartFile[0], factory));
    }

    @Test
    void rejectsNullBatchMember() throws IOException {
        MultipartFile valid = imageFile("art.png", "png", 40, 80, Color.RED);
        assertThrows(
                IllegalArgumentException.class,
                () -> PdfUtils.createColoringBook(new MultipartFile[] {valid, null}, factory));
    }

    @Test
    void rejectsEmptyMemberWithSafeFilename() throws IOException {
        MultipartFile valid = imageFile("art.png", "png", 40, 80, Color.RED);
        MultipartFile empty =
                new MockMultipartFile("fileInput", "../../empty.png", "image/png", new byte[0]);
        IllegalArgumentException exception =
                assertThrows(
                        IllegalArgumentException.class,
                        () ->
                                PdfUtils.createColoringBook(
                                        new MultipartFile[] {valid, empty}, factory));
        assertTrue(exception.getMessage().contains("empty.png"));
        assertFalse(exception.getMessage().contains("../"));
    }

    @Test
    void corruptLaterImageFailsWholeBatchAndClosesDocument() throws IOException {
        MultipartFile valid = imageFile("art.png", "png", 40, 80, Color.RED);
        MultipartFile corrupt =
                new MockMultipartFile(
                        "fileInput", "../../broken.png", "image/png", new byte[] {1, 2, 3});
        IOException exception =
                assertThrows(
                        IOException.class,
                        () ->
                                PdfUtils.createColoringBook(
                                        new MultipartFile[] {valid, corrupt}, factory));
        assertTrue(exception.getMessage().contains("broken.png"));
        assertFalse(exception.getMessage().contains("../"));
        assertTrue(composedDocument.getDocument().isClosed());
    }

    @Test
    void corruptLaterTiffFrameFailsWholeBatchAndClosesDocument() throws IOException {
        byte[] bytes = tiff();
        ByteBuffer data =
                ByteBuffer.wrap(bytes)
                        .order(bytes[0] == 'I' ? ByteOrder.LITTLE_ENDIAN : ByteOrder.BIG_ENDIAN);
        int firstDirectory = data.getInt(4);
        int secondDirectory =
                data.getInt(
                        firstDirectory
                                + 2
                                + 12 * Short.toUnsignedInt(data.getShort(firstDirectory)));
        int entries = Short.toUnsignedInt(data.getShort(secondDirectory));
        boolean corrupted = false;
        for (int i = 0; i < entries; i++) {
            int entry = secondDirectory + 2 + 12 * i;
            if (Short.toUnsignedInt(data.getShort(entry)) == 259) {
                data.putShort(entry + 8, (short) 65535);
                corrupted = true;
            }
        }
        assertTrue(corrupted);
        MultipartFile corrupt =
                new MockMultipartFile("fileInput", "later-frame.tiff", "image/tiff", bytes);
        assertThrows(
                IOException.class,
                () -> PdfUtils.createColoringBook(new MultipartFile[] {corrupt}, factory));
        assertEquals(2, composedDocument.getNumberOfPages());
        assertTrue(composedDocument.getDocument().isClosed());
    }

    @ParameterizedTest
    @CsvSource({"false", "true"})
    void closesEveryOpenedUploadStreamOnSuccessOrFailure(boolean corrupt) throws IOException {
        List<Boolean> closed = new ArrayList<>();
        byte[] bytes =
                corrupt ? new byte[] {1, 2, 3} : encoded(solidImage(40, 80, Color.RED), "png");
        MultipartFile file =
                new MockMultipartFile("fileInput", "stream.png", "image/png", bytes) {
                    @Override
                    public InputStream getInputStream() {
                        int index = closed.size();
                        closed.add(false);
                        return new FilterInputStream(new ByteArrayInputStream(bytes)) {
                            @Override
                            public void close() throws IOException {
                                closed.set(index, true);
                                super.close();
                            }
                        };
                    }
                };
        if (corrupt) {
            assertThrows(
                    IOException.class,
                    () -> PdfUtils.createColoringBook(new MultipartFile[] {file}, factory));
        } else {
            try (PDDocument pdf = create(file)) {
                assertEquals(2, pdf.getNumberOfPages());
            }
        }
        assertFalse(closed.isEmpty());
        assertTrue(closed.stream().allMatch(Boolean::booleanValue));
    }

    private PDDocument create(MultipartFile... files) throws IOException {
        return Loader.loadPDF(PdfUtils.createColoringBook(files, factory));
    }

    private static void assertBookPages(PDDocument pdf, Color... colors) throws IOException {
        for (PDPage page : pdf.getPages()) {
            assertEquals(PDRectangle.A4.getWidth(), page.getMediaBox().getWidth(), 0.01);
            assertEquals(PDRectangle.A4.getHeight(), page.getMediaBox().getHeight(), 0.01);
            assertEquals(0, page.getRotation());
        }
        PDFRenderer renderer = new PDFRenderer(pdf);
        for (int i = 0; i < colors.length; i++) {
            BufferedImage image = renderer.renderImage(i * 2);
            assertColorNear(colors[i], image.getRGB(image.getWidth() / 2, image.getHeight() / 2));
            assertBlank(pdf, i * 2 + 1);
        }
    }

    private static void assertBlank(PDDocument pdf, int pageIndex) throws IOException {
        PDPage page = pdf.getPage(pageIndex);
        assertFalse(page.hasContents());
        if (page.getResources() != null) {
            assertFalse(page.getResources().getXObjectNames().iterator().hasNext());
        }
        BufferedImage image = new PDFRenderer(pdf).renderImage(pageIndex);
        for (int y = 0; y < image.getHeight(); y++) {
            for (int x = 0; x < image.getWidth(); x++) {
                assertEquals(0xFFFFFF, image.getRGB(x, y) & 0xFFFFFF);
            }
        }
    }

    private static void assertPlacement(PDPage page, int width, int height) throws IOException {
        List<Object> tokens = new PDFStreamParser(page).parse();
        double scale =
                Math.min(PDRectangle.A4.getWidth() / width, PDRectangle.A4.getHeight() / height);
        double[] expected = {
            width * scale,
            0,
            0,
            height * scale,
            (PDRectangle.A4.getWidth() - width * scale) / 2,
            (PDRectangle.A4.getHeight() - height * scale) / 2
        };
        int matrices = 0;
        for (int i = 6; i < tokens.size(); i++) {
            if (tokens.get(i) instanceof Operator operator && "cm".equals(operator.getName())) {
                for (int j = 0; j < 6; j++) {
                    assertEquals(
                            expected[j], ((COSNumber) tokens.get(i - 6 + j)).floatValue(), 0.01);
                }
                matrices++;
            }
        }
        assertEquals(1, matrices);
    }

    private static void assertColorNear(Color expected, int rgb) {
        Color actual = new Color(rgb);
        assertEquals(expected.getRed(), actual.getRed(), 6);
        assertEquals(expected.getGreen(), actual.getGreen(), 6);
        assertEquals(expected.getBlue(), actual.getBlue(), 6);
    }

    private static MultipartFile imageFile(
            String name, String format, int width, int height, Color color) throws IOException {
        return new MockMultipartFile(
                "fileInput",
                name,
                "jpg".equals(format) ? "image/jpeg" : "image/png",
                encoded(solidImage(width, height, color), format));
    }

    private static BufferedImage solidImage(int width, int height, Color color) {
        BufferedImage image = new BufferedImage(width, height, BufferedImage.TYPE_INT_RGB);
        Graphics2D graphics = image.createGraphics();
        graphics.setColor(color);
        graphics.fillRect(0, 0, width, height);
        graphics.dispose();
        return image;
    }

    private static byte[] encoded(BufferedImage image, String format) throws IOException {
        ByteArrayOutputStream output = new ByteArrayOutputStream();
        assertTrue(ImageIO.write(image, format, output));
        return output.toByteArray();
    }

    private static byte[] tiff() throws IOException {
        ImageWriter writer = ImageIO.getImageWritersByFormatName("tiff").next();
        ByteArrayOutputStream output = new ByteArrayOutputStream();
        try (ImageOutputStream imageOutput = ImageIO.createImageOutputStream(output)) {
            writer.setOutput(imageOutput);
            writer.prepareWriteSequence(null);
            for (Color color : new Color[] {Color.RED, Color.BLUE}) {
                writer.writeToSequence(
                        new IIOImage(solidImage(40, 80, color), null, null),
                        writer.getDefaultWriteParam());
            }
            writer.endWriteSequence();
        } finally {
            writer.dispose();
        }
        return output.toByteArray();
    }

    private static byte[] jpegWithExifOrientation(byte[] jpeg) throws IOException {
        ByteBuffer exif = ByteBuffer.allocate(50).order(ByteOrder.LITTLE_ENDIAN);
        exif.put(new byte[] {'E', 'x', 'i', 'f', 0, 0});
        exif.putShort((short) 0x4949).putShort((short) 42).putInt(8);
        exif.putShort((short) 1)
                .putShort((short) 0x8769)
                .putShort((short) 4)
                .putInt(1)
                .putInt(26)
                .putInt(0);
        exif.putShort((short) 1)
                .putShort((short) 0x0112)
                .putShort((short) 3)
                .putInt(1)
                .putShort((short) 6)
                .putShort((short) 0)
                .putInt(0);
        ByteArrayOutputStream output = new ByteArrayOutputStream();
        output.write(jpeg, 0, 2);
        output.write(new byte[] {(byte) 0xFF, (byte) 0xE1, 0, 52});
        output.write(exif.array());
        output.write(jpeg, 2, jpeg.length - 2);
        return output.toByteArray();
    }
}
